from wd_common import *
i=1
Z=lambda q,a:[('z',q),('b',a)]
def face(mark=''):
    return '<circle r="60" fill="#e8c3a0"/><path d="M-60 -10 q0 -70 60 -70 q60 0 60 70 q-10 -50 -60 -50 q-50 0 -60 50z" fill="#2a1a10"/><ellipse cx="-22" cy="4" rx="7" ry="4" fill="#2a1a10"/><ellipse cx="22" cy="4" rx="7" ry="4" fill="#2a1a10"/><path d="M-12 34 q12 8 24 0" stroke="#7a3b1f" stroke-width="3" fill="none"/>'+mark
TRI='<path d="M-30 -30 h60 M-30 -22 h60 M-30 -14 h60" stroke="#f4f1ea" stroke-width="4"/><circle cy="-22" r="4" fill="#d02a2a"/>'
NAMAM='<path d="M-12 -6 L-12 -50 M12 -6 L12 -50 M-12 -6 q12 10 24 0" stroke="#f4f1ea" stroke-width="5" fill="none"/><path d="M0 -8 v-42" stroke="#d02a2a" stroke-width="4"/>'
MADHVA='<path d="M-8 -6 v-44 M8 -6 v-44" stroke="#e9d6a0" stroke-width="4"/><path d="M0 -10 v-38" stroke="#1b1b1b" stroke-width="3"/><circle cy="-22" r="3.5" fill="#e0a800"/>'
DOT='<circle cy="-18" r="7" fill="#d02a2a"/>'
def bowl(c): return f'<ellipse rx="24" ry="8" fill="#c9a227"/><ellipse cy="-4" rx="18" ry="5" fill="{c}"/>'
fw=foreword(i,['A line of ash across the forehead, a red dot between the brows, a white U with a red stroke down the middle: from a glance at someone’s forehead in an Indian temple you can often tell which god they worship. This is <b>tilaka</b>, the sacred mark.',
 'This part explains the name, where it is worn and why there, what it is made of, the main forms of Śaivas, Vaiṣṇavas and Śāktas, how it is applied, the kuṅkuma of married women, the marks on the body, and what the teachers say it means.',
 'Previous: '+L('/why-do-we/arati/','ārati')+'. Next: '+L('/why-do-we/prasada/','prasāda')+'. Śiva’s ash and the Vaiṣṇava nāmam connect with '+L('/shiva/who-is-shiva/','Who is Śiva')+' and '+L('/vishnu/who-is-vishnu/','Who is Viṣṇu')+'.'],Z('Is tilaka the same as a bindi?','A bindi is one kind of mark, usually a dot. Tilaka is the whole family of sacred marks.'))
gl=glance([('Name','Tilaka (tilak, tilakam); also puṇḍra'),('Where','Mainly the forehead, between and above the brows'),('Śaiva','Tripuṇḍra: three horizontal lines of sacred ash'),('Vaiṣṇava','Ūrdhvapuṇḍra: vertical marks, often U-shaped'),('Śākta / Devī','A red dot or line of kuṅkuma'),('Materials','Sacred ash, sandal paste, kuṅkuma, turmeric, gopīcandana clay'),('When','After bathing, before worship; at temples; festivals'),('Finger','Commonly the ring finger'),('Married women','Kuṅkuma at the brow and parting, by custom'),('Meaning','A sign of the god, of purity and of the inner eye')],
 S('Four faces with four marks: three lines of ash, a white U with red line, a clay mark with black line, a red dot',''.join(g(80+k*133,140,.8,face(m)) for k,m in enumerate([TRI,NAMAM,MADHVA,DOT]))+''.join(T(80+k*133,226,t,10) for k,t in enumerate(['Śaiva','Śrīvaiṣṇava','Mādhva','Devī'])),'#fff3cf',230),Z('Can I tell someone’s god from the mark?','Often. Not always: many wear more than one, or just a dot.'),'A god <b>written on the brow</b>.')
name=reading('name','THE NAME','Tilaka and puṇḍra',S('A sesame plant beside a forehead mark',g(160,200,1.6,'<path d="M0 0 v-80" stroke="#2f8a3a" stroke-width="4"/>'+''.join(f'<ellipse cx="{8*((k%2)*2-1)}" cy="{-20-k*14}" rx="8" ry="4" fill="#3a8a4a"/>' for k in range(5)))+g(380,170,1.3,face(DOT)),'#fff3cf',215),
 ['<b>Tilaka.</b> The Sanskrit word for the mark. Some link it to tila, the sesame seed, for its small size. (Etymologies differ.)','<b>Puṇḍra.</b> Texts often say <b>puṇḍra</b>: tri-puṇḍra, “three lines”, and ūrdhva-puṇḍra, “upward mark”.','<b>Regional words.</b> Kannaḍa nāma, Tamiḻ nāmam, Hindi ṭīkā and bindī.','<b>Not only a dot.</b> A tilaka may be a dot, a line, a U, three lines or a combination.','<b>Shared.</b> Jains also wear sacred marks in their worship.'],Z('So “nāma” is the Vaiṣṇava mark?','In the south, yes: the nāmam. It literally means “name”, the Lord’s name worn on the brow.'),'A mark, <b>a name, a sign</b>.')
where=reading('where','WHY THE BROW','Between the eyebrows',S('A face with a glowing point between the eyebrows',g(280,170,1.8,face('<circle cy="-14" r="8" fill="#e0a800"/><circle cy="-14" r="20" fill="#e0a800" opacity=".25"/>')),'#20243a',230),
 ['<b>The spot.</b> The main mark goes on the forehead, centred between and above the eyebrows.','<b>Ājñā.</b> In yoga this point is the <b>ājñā cakra</b>, the centre of command and inner sight. Marking it is read as honouring the inner eye. (Interpretation.)','<b>Śiva’s eye.</b> Śiva’s third eye is shown on the forehead; the mark echoes it for Śaivas. (Interpretation.)','<b>The face we show.</b> The forehead is the first thing seen: the mark declares faith openly.','<b>Cooling.</b> Sandal paste is said to cool the head. (Popular belief.)'],Z('Is there really an eye there?','In meditation, teachers say. In the mirror, just a forehead. The mark reminds you of the first.'),'The mark <b>on the inner eye</b>.')
mat=cards('materials','WHAT IT IS MADE OF','Ash, sandal, red and clay',fig_row('Bowls of ash, sandal paste, red powder, turmeric and pale clay',[(bowl('#d9d4cc'),1.2),(bowl('#e9c27a'),1.2),(bowl('#d02a2a'),1.2),(bowl('#f0b020'),1.2),(bowl('#efe6c8'),1.2)],['vibhūti','candana','kuṅkuma','haridrā','gopīcandana'],gy=150),
 [('⚪','Vibhūti','Sacred ash, traditionally from burnt cow dung and offerings; Śiva’s mark.'),('🟤','Candana','Sandal paste, fragrant and cooling; used by all traditions.'),('🔴','Kuṅkuma','Red powder of turmeric and lime; the Devī’s colour.'),('🟡','Haridrā','Turmeric, auspicious and protective.'),('🏺','Gopīcandana','A pale clay linked with Dvārakā; used by many Vaiṣṇavas.'),('⚫','Aṅgāra','Charcoal from the sacrificial fire, in some Vaiṣṇava marks.')],None,'Each tradition <b>has its material</b>.',intro='Materials vary by tradition, region and family.')
shaiva=reading('tripundra','TRIPUṆḌRA','Three lines of ash',S('A man with three ash lines and rudrākṣa beside a liṅga',g(180,170,1.5,face(TRI))+g(400,200,1.2,'<ellipse rx="40" ry="10" fill="#7a6a5a"/><rect x="-14" y="-50" width="28" height="50" rx="14" fill="#5a5a5a"/>'+'<path d="M-12 -40 h24 M-12 -34 h24 M-12 -28 h24" stroke="#f4f1ea" stroke-width="2"/>'),'#e3eaf3',215),
 ['<b>The form.</b> Three horizontal lines of vibhūti across the forehead, often with a red or sandal dot in the middle.','<b>On the liṅga too.</b> The same three lines are drawn on the Śiva liṅga.','<b>Readings.</b> The three lines are read as many triads: the three guṇas, three worlds, three Vedas, or the three impurities burnt away. (Interpretations.)','<b>Ash.</b> Ash is what remains when everything is burnt: a reminder of impermanence and of Śiva who wears it. (Interpretation.)','<b>On the body.</b> Devout Śaivas also mark the arms, chest and other places.'],Z('Why ash of all things?','Everything ends as ash. Śiva wears it as if to say: I am what remains.'),'Three lines <b>of what remains</b>.')
vaish=reading('urdhvapundra','ŪRDHVAPUṆḌRA','The upward mark of the Vaiṣṇavas',S('Faces with a Śrīvaiṣṇava nāmam and a Mādhva gopīcandana mark',g(180,170,1.5,face(NAMAM))+g(400,170,1.5,face(MADHVA)),'#e3eaf3',230),
 ['<b>Upward.</b> Vaiṣṇava marks are vertical, rising from the bridge of the nose: commonly read as the path upward to Viṣṇu. (Interpretation.)','<b>Śrīvaiṣṇava.</b> The nāmam: a white U (or Y) with a red or yellow line in the centre, standing for Lakṣmī; Vaḍakalai and Teṅkalai forms differ at the base.','<b>Mādhva.</b> Two vertical lines of gopīcandana with a black line of aṅgāra between and a yellow or red dot, a form familiar in Uḍupi.','<b>Gauḍīya.</b> A U of gopīcandana with a small leaf shape on the nose.','<b>Viṣṇu’s feet.</b> The U is often explained as the Lord’s footprint. (Interpretation.)'],Z('So many Vaiṣṇava marks?','One god, many schools. The mark tells you which teacher a family follows.'),'Rising <b>toward Viṣṇu</b>.')
devi_=reading('kumkuma','KUṄKUMA','The red mark of the Devī',S('A woman applying a red dot; a goddess image with a red forehead mark',g(170,170,1.5,face(DOT))+g(400,200,1.4,devi(sari='#c0392b',items=('lotus',))),'#fff3cf',215),
 ['<b>Red.</b> Kuṅkuma is the Devī’s colour: life, power, auspiciousness.','<b>Śāktas.</b> Devotees of the Goddess wear a red dot or vertical red line.','<b>Prasāda.</b> In Devī temples, kuṅkuma from the worship is given as prasāda and worn at once.','<b>Combined.</b> Many people wear sandal with a kuṅkuma dot, or ash with a red dot.','<b>Śrīvidyā.</b> In Śrīvidyā worship kuṅkuma has a special place (see '+L('/srividya/','Śrīvidyā')+').'],Z('Is it only for women?','No. Men wear kuṅkuma too, especially at Devī temples.'),'The Goddess’s <b>red</b>.')
apply=reading('apply','HOW IT IS APPLIED','After the bath, before worship',S('A man in a mirror applying a mark with his ring finger',g(200,215,1.6,person('#f4f1ea'))+'<rect x="330" y="60" width="140" height="150" rx="10" fill="#bfe3ff" stroke="#7a3b1f" stroke-width="6"/>'+g(400,150,.9,face(TRI)),'#fff3cf',215),
 ['<b>Time.</b> Tilaka is put on after bathing and before daily worship, and again at temples and festivals.','<b>Finger.</b> The ring finger is commonly used for most marks; some traditions specify others. (Practices differ.)','<b>With prayer.</b> Many recite a name of God or a short prayer while applying it.','<b>Facing a direction.</b> Many face east or north. (Common custom.)','<b>Not for show.</b> Traditional teaching treats it as part of worship, not decoration.'],Z('Can I put it on without a bath?','At a temple, people do. Your grandmother will have opinions.'),'Bathe, pray, <b>then mark</b>.')
married=reading('married','KUṄKUMA AND MARRIAGE','The mark of the married woman',S('A bride with kuṅkuma at the brow and in the hair parting',g(280,170,1.8,face('<circle cy="-18" r="7" fill="#d02a2a"/><path d="M0 -60 v-20" stroke="#d02a2a" stroke-width="5"/>')),'#fff3cf',230),
 ['<b>By custom.</b> In many communities a married woman wears kuṅkuma on the forehead, and in the north sindūr in the hair parting.','<b>At the wedding.</b> The groom applies it in some wedding rites.','<b>Haḷadi-kuṅkuma.</b> In Karnataka, women exchange turmeric and kuṅkuma at gatherings such as Gauri and Varamahālakṣmī (see '+L('/festivals/varamahalakshmi/','Varamahālakṣmī')+').','<b>Changing customs.</b> Customs around the mark and widowhood vary widely and are changing; this site describes, not prescribes.','<b>Fashion.</b> The decorative bindi is now worn by many regardless of marriage.'],Z('Is the bindi religious?','The kuṅkuma dot began as sacred. Today it may be faith, custom or style; only the wearer can say.'),'Red <b>at the threshold of life</b>.')
body=reading('body','MARKS ON THE BODY','Twelve and more places',S('A figure with marks on forehead, arms, chest and belly',g(280,215,2.4,person('#f4f1ea'))+''.join(f'<path d="M{x} {y} v-10" stroke="#d02a2a" stroke-width="3"/>' for x,y in [(280,80),(250,130),(310,130),(280,140),(280,170),(240,170),(320,170)]),'#fff3cf',230),
 ['<b>Not only the brow.</b> Devout Vaiṣṇavas may wear marks in twelve places (dvādaśa puṇḍra), each linked with a name of Viṣṇu. (As described in Vaiṣṇava manuals.)','<b>Śaivas.</b> Śaivas may apply ash on many places: arms, chest, belly, back.','<b>Mudrās.</b> Mādhvas also stamp the conch and discus (mudrā) in gopīcandana on the body.','<b>Daily or special.</b> Full body marks are worn by priests and the devout daily, by others on special days.','<b>Mantras.</b> Each mark has its name or prayer, learned from a teacher.'],Z('Twelve marks every morning?','The priests do it in a minute. Practice makes it quick.'),'The whole body <b>as a temple</b>.')
st=story('story','THE FIRST TILAKA','Ravi at the temple',strip('Three panels: a boy at the temple; the priest gives kuṅkuma; the boy shows his grandfather',
 [('<rect width="144" height="190" fill="#fff3cf"/>'+g(50,180,.7,person('#1d4f8a'))+g(110,170,.5,tulu_temple()),'#fff3cf'),
  ('<rect width="144" height="190" fill="#fff3cf"/>'+g(40,180,.8,person('#f4f1ea'))+g(100,180,.6,person('#1d4f8a'))+'<circle cx="100" cy="128" r="3" fill="#d02a2a"/>','#fff3cf'),
  ('<rect width="144" height="190" fill="#fff3cf"/>'+g(72,110,.7,face(TRI)),'#fff3cf')],['the temple','the kuṅkuma','the mark']),'A temple visit (an illustrative story).',
 ['Ravi, seven, stands in line at the Śiva temple with his grandfather.','The priest dips a finger in the ash and draws three lines on Ravi’s forehead, then a red dot.','“Now Śiva knows you came,” says Grandfather. Ravi does not wash his face till bedtime.'])
mean=reading('meaning','WHAT IT MEANS','Readings of the teachers',S('A forehead mark glowing like a small lamp',g(280,170,1.8,face('<circle cy="-18" r="8" fill="#e0a800"/>'))+g(280,60,.8,flame()),'#20243a',230),
 ['<b>Belonging.</b> The mark says: I belong to this god and this tradition.','<b>Remembering.</b> Seen in the mirror or felt on the skin, it recalls God through the day. (Common teaching.)','<b>Purity.</b> Worn after bathing, it marks the body as ready for worship.','<b>Inner sight.</b> Placed at the ājñā point, it honours the inner eye. (Interpretation.)','<b>Grace received.</b> Prasāda kuṅkuma or ash carries the temple’s blessing home.'],Z('If I forget it one day?','Then remember God without it. The mark is a reminder, not a ticket.'),'A reminder <b>you wear</b>.')
endp=end(i,['<b>Name.</b> Tilaka, puṇḍra, nāma: the sacred mark.','<b>Where.</b> The brow, at the ājñā point; also body marks.','<b>Forms.</b> Tripuṇḍra (Śaiva), ūrdhvapuṇḍra (Vaiṣṇava), kuṅkuma (Devī).','<b>Materials.</b> Ash, sandal, kuṅkuma, turmeric, gopīcandana.','<b>Meaning.</b> Belonging, remembrance, purity, inner sight.'],'Part 3 is prasāda.','A god on the brow')
src=sources([('Practice:','Wikipedia, “Tilaka” (forms, materials, Śaiva tripuṇḍra, Vaiṣṇava ūrdhvapuṇḍra, Śrīvaiṣṇava, Mādhva and Gauḍīya marks, twelve marks); common temple and household practice in Karnataka (haḷadi-kuṅkuma).')],'the sesame etymology, finger and direction customs, and the readings of lines and shapes are commonly taught but vary; meanings marked as interpretation are teachers’ readings.','No verse or mantra text is reproduced in this part.')
finish(i,'PART 2 OF 10 · ASH · SANDAL · KUṄKUMA',covart('Four faces with Śaiva, Śrīvaiṣṇava, Mādhva and Devī marks',''.join(g(60+k*107,130,.65,face(m)) for k,m in enumerate([TRI,NAMAM,MADHVA,DOT]))),'A god on the brow',
 'Why we wear <b>tilaka</b>: the name, why the brow, the materials, the <b>tripuṇḍra</b>, the Vaiṣṇava <b>nāmam</b>, kuṅkuma, how it is applied and what it means.',
 'Why do we wear tilaka? Explained and illustrated: name and puṇḍra, the ājñā point, vibhūti, sandal, kuṅkuma and gopīcandana, Śaiva tripuṇḍra, Vaiṣṇava ūrdhvapuṇḍra, Devī kuṅkuma, marriage customs, body marks and meanings.',
 [fw,gl,name,where,mat,shaiva,vaish,devi_,apply,married,body,st,mean,endp,src])
